'use strict';
// Sponsor workflow ported from the supplied Framing, Intake and Review steps.
let setupDraftPreviewProject=null;
let sponsorStage='framing',sponsorQuestion='q2',sponsorFit=false,sponsorValidation=null,sponsorCoachResult=null;
const sponsorReviewerDrafts=new Map(),sponsorPreparedReviews=new Map();
function sponsorReviewerKey(){return typeof reviewerDraftKey==='function'?reviewerDraftKey('sponsor-intake'):[state.auth?.account?.id||'',state.actor||'',state.project?.id||state.intake?.draft?.ref?.id||''].join('|');}
function sponsorReviewerMessage(){return typeof reviewerDraftRead==='function'?reviewerDraftRead('sponsor-intake'):sponsorReviewerDrafts.get(sponsorReviewerKey())||'';}
function sponsorReviewerWrite(text){if(typeof reviewerDraftWrite==='function')reviewerDraftWrite('sponsor-intake',text);else sponsorReviewerDrafts.set(sponsorReviewerKey(),String(text||''));}
function sponsorReviewerCapture(composer){if(composer?.dataset?.reviewerDraftKey&&composer.dataset.reviewerDraftKey!==sponsorReviewerKey())throw Error('The project or role changed. Reopen the AI partner before asking.');const message=String(composer?.value??sponsorReviewerMessage());sponsorReviewerWrite(message);return message;}
function sponsorReviewerComposer(id,action,question=''){return `<div class="sponsor-chat-input reviewer-composer"><label class="reviewer-speaker" for="${id}">You</label><textarea id="${id}" class="integrity-review-input" data-reviewer-draft="sponsor-intake" data-reviewer-scope="" aria-label="Ask your AI partner" rows="5" maxlength="20000" placeholder="Ask your AI partner">${esc(sponsorReviewerMessage())}</textarea><button type="button" class="primary" data-action="${action}"${question?` data-id="${esc(question)}"`:''} ${coachInfo().model.configured?'':'disabled'}>Ask</button></div>`;}
const sponsorSteps=[['framing','Business Intent'],['brief','Context'],['planning','Requirements set up'],['review','Review & publish']];
const sponsorFitLabels={beneficiaries:'Primary users',jobs:'Jobs to be done',need:'Pains and unmet needs',gains:'Desired gains',approach:'Proposed offering',job_support:'How the offering supports the job',pain_relievers:'How it relieves the pain',gain_creators:'How it creates the gain',value:'Working value proposition',why_now:'Why invest now?',strategic_relevance:'Business objective',investment_case:'Investment case',assumptions:'Assumptions to investigate',research_question:'What should Research investigate?',operations_question:'What should Design explore?'};
function sponsorInfo(){return state.sponsor;}
function sponsorText(name,title,value='',help='',rows=3){return `<label class="sponsor-field"><span>${esc(title)}</span>${help?`<small>${esc(help)}</small>`:''}<textarea name="${esc(name)}" rows="${rows}" maxlength="20000">${esc(value)}</textarea></label>`;}
function sponsorStepsNav(stage){return `<nav class="sponsor-steps" aria-label="Business development stages">${sponsorSteps.map(([id,title],i)=>`<button type="button" data-action="sponsor-step" data-id="${id}" ${id===stage?'aria-current="step"':''}><span class="sponsor-step-number" aria-hidden="true">${i+1}</span>${title}</button>`).join('')}</nav>`;}
function sponsorPanel(title,body,actions=''){return `<section class="sponsor-panel"><div class="sponsor-panel-head"><h2>${esc(title)}</h2>${actions}</div><div class="sponsor-panel-body">${body}</div></section>`;}
function sponsorScreen(){
 if(!sponsorInfo())return sponsorBriefStart();
 if(intakeStep==='learning')return intentRefinementSection();
 if(intakeCaseId)return intakeReviewScreen();
 if(intakeStep==='review')sponsorStage='review';
 return `<div class="sponsor-surface">${sponsorStage==='review'?sponsorReview():sponsorStage==='brief'?sponsorBrief():sponsorFraming()}</div>`;
}
function sponsorAnswerHas(a){return a.items.some(x=>x.trim())||a.roles.some(r=>r.name.trim());}
function sponsorFitEditor(){const v=state.intake.draft.body.values;return `<form id="sponsor-editor" data-kind="fit"><div class="sponsor-error" role="alert"></div><h2>Value proposition & investment</h2><p>Match the value offered to users’ jobs, pains and gains. Keep the financial investment case distinct.</p>${sponsorText('beneficiaries','Primary users',v.beneficiaries)}${[['jobs','job_support'],['need','pain_relievers'],['gains','gain_creators']].map(pair=>`<div class="sponsor-fit-pair">${pair.map(k=>sponsorText(k,sponsorFitLabels[k],v[k])).join('')}</div>`).join('')}${sponsorText('approach',sponsorFitLabels.approach,v.approach)}${sponsorText('value',sponsorFitLabels.value,v.value,'Who is this for, which job/pain/gain matters, and how does the proposed offering help?',5)}<details><summary>Business rationale & investment</summary><p class="caption">What Research and Design must validate is set in Context, under Validation plan.</p>${['strategic_relevance','why_now','investment_case'].map(k=>sponsorText(k,sponsorFitLabels[k],v[k]||'',k==='investment_case'?'State benefits, alternatives, resource needs, one-time costs, run costs, timeframe and uncertainty. Estimates need a basis.':'')).join('')}</details><div class="sponsor-actions">${button('Save draft','sponsor-save','','primary')}${button('Review value proposition','sponsor-accept-value')}</div><p class="caption">Review records your starting hypothesis. It does not establish evidence or approve investment.</p></form>`;}
function sponsorCoachOutput(){const r=coachInfo().runs.find(r=>r.ref.id===sponsorCoachResult.id);if(!r)return '<p>AI partner response unavailable in this role.</p>';return '<p class="reviewer-speaker">AI partner</p>'+para(r.body.output.reply)+(r.body.output.suggestions||[]).map(s=>`<div class="ac-suggestion">${typeof acSuggestionHead==='function'?acSuggestionHead('From your AI partner · edit it after using; it counts once you save'):''}<p class="ac-suggestion-label">Suggested wording</p>${para(s.text)}<p class="caption">${esc(s.rationale||'')}</p>${citationsHtml(s.citations||[])}${sponsorQuestion!=='q4'?button('Use suggested response','sponsor-use-advice',r.ref.id,'small'):''}</div>`).join('')+(r.body.output.questions||[]).map(q=>para(q.question)).join('');}
function sponsorFormData(){
 const form=$('#sponsor-editor');if(!form)return null;const fd=new FormData(form),kind=form.dataset.kind;
 if(kind==='framing')return {framing_completed:Object.fromEntries(Array.from(form.querySelectorAll('[data-framing-complete]')).map(el=>[el.dataset.framingComplete,el.checked])),framing:{name:fd.get('name'),context:fd.get('context'),statement:fd.get('statement'),summary:Object.fromEntries(['problem','solution','risk','options'].map(k=>[k,fd.get('summary-'+k)]))},fit:Object.fromEntries(['value','gains','why_now'].map(k=>[k,fd.get('fit-'+k)]))};
 if(kind==='fit')return {fit:Object.fromEntries(fd)};
 const q=form.dataset.question,old=sponsorInfo().brief.answers[q],roles=q==='q4'?Array.from(form.querySelectorAll('[data-role-index]')).map(el=>Object.fromEntries(['name','does','needs','where','often'].map(k=>[k,el.querySelector(`[name="role-${el.dataset.roleIndex}-${k}"]`).value]))):[];
 return {answers:{[q]:{roles,items:q==='q4'?[]:fd.getAll('answer').map(t=>String(t)),completed:fd.get('completed')==='on',confirmed:old.confirmed&&JSON.stringify({items:q==='q4'?[]:fd.getAll('answer').map(t=>String(t)),roles})===JSON.stringify({items:old.items,roles:old.roles})}}};
}
function sponsorSaveStatus(text){
 const status=$('#sponsor-save-status');if(!status)return;
 status.textContent=text;
 if(status.dataset)status.dataset.saveState=text==='Draft saved'?'saved':text==='Not saved'?'error':'unsaved';
 if(text==='Draft saved'&&status.style){status.style.animation='none';void status.offsetWidth;status.style.animation='';}
}
// Stale save: reload the newer version, then put the person's unsaved text back so nothing typed is lost.
async function sponsorKeepTextAfterStale(){const form=document.getElementById('sponsor-editor');if(!form)return;const kept=[...form.elements].filter(e=>e.name&&'value' in e&&e.type!=='checkbox'&&e.type!=='radio').map(e=>[e.name,e.value]);await load();render();const next=document.getElementById('sponsor-editor');if(!next)return;let restored=0;for(const [n,v] of kept){const el=next.elements?.[n];if(el&&'value' in el&&el.value!==v){el.value=v;restored++;}}pageDirty=restored>0;sponsorSaveStatus(restored?'Your text is kept. Save again to replace the newer version':'Draft saved');}
async function saveSponsorDraft(){
 const data=sponsorFormData();if(!data||!pageDirty)return;
 const snapshot=JSON.stringify(data);try{await command('sponsor-save',{expected:state.intake.draft.ref,...data});await load();if(typeof syncProjectPageIdentity==='function')syncProjectPageIdentity();}catch(error){if(/changed/i.test(error.message||'')&&/reload|reopen/i.test(error.message||'')){await sponsorKeepTextAfterStale();throw Error('A newer version was saved elsewhere. Your text is kept here; review it and save again.');}sponsorSaveStatus('Not saved');throw error;}
 pageDirty=JSON.stringify(sponsorFormData())!==snapshot;sponsorSaveStatus(pageDirty?'Unsaved edits':'Draft saved');
 sponsorSyncQuestionProgress(pageDirty);
 if(pageDirty)throw Error('New edits arrived during saving. Save those before continuing.');
}
async function dispatchSponsorAction(action,id,origin){
 if(action==='intake-step'&&state.actor==='priya'){await saveBeforeProjectChange();intakeCaseId=null;intakeStep=id;selected=null;view=id==='drawers'?(state.intake.setup_governance?.enabled&&!state.intake.setup_governance.editable?'requirements':'planning'):'intent';setupDraftPreviewProject=null;sponsorStage=id==='review'?'review':id==='rationale'?'framing':'brief';sponsorFit=id==='value';render();return true;}
 if(!action.startsWith('sponsor-'))return false;
 if(action==='sponsor-planning-focus'){openPlanningField(id);return true;}
 if(action==='sponsor-planning-toggle'){const panel=document.getElementById(id);if(panel?.matches('details.planning-category-settings')){panel.open=!panel.open;origin?.setAttribute('aria-expanded',String(panel.open));}return true;}
 if(action==='sponsor-item-add'||action==='sponsor-item-remove'){
  const list=document.querySelector('#sponsor-answer-items');if(!list)return true;
  if(action==='sponsor-item-add'){if(list.children.length>=40)throw Error('Keep this response to 40 items or fewer.');list.insertAdjacentHTML('beforeend',sponsorListItem('',list.children.length));list.lastElementChild.querySelector('textarea').focus();}
  else {const row=origin?.closest('.sponsor-list-item');if(!row)return true;const index=[...list.children].indexOf(row);row.remove();if(!list.children.length)list.insertAdjacentHTML('beforeend',sponsorListItem('',0));list.children[Math.min(index,list.children.length-1)].querySelector('textarea').focus();}
  [...list.children].forEach((row,i)=>{row.querySelector('.sponsor-item-number').textContent=i+1;row.querySelector('.sr-only').textContent='Answer item '+(i+1);row.querySelector('button').setAttribute('aria-label','Remove answer item '+(i+1));});pageDirty=true;const completed=$('#sponsor-editor [name=completed]');if(completed)completed.checked=false;sponsorSyncQuestionProgress(true);sponsorSaveStatus('Unsaved edits');return true;
 }
 if(action==='sponsor-scroll'){const section=document.querySelector('#sponsor-review-'+id);section?.scrollIntoView({block:'start'});section?.focus({preventScroll:true});return true;}

 if(action==='sponsor-framing-complete'){
  const checkbox=origin;pageDirty=true;
  try{await saveSponsorDraft();}
  catch(error){if(checkbox)checkbox.checked=false;pageDirty=true;sponsorSaveStatus('Not saved');throw error;}
  return true;
 }
 if(action==='sponsor-complete'){
  pageDirty=true;sponsorSyncQuestionProgress(true);const checkbox=$('#sponsor-editor [name=completed]');
  try{await saveSponsorDraft();}
  catch(error){if(checkbox){checkbox.checked=false;checkbox.disabled=false;}pageDirty=true;sponsorSyncQuestionProgress(true);sponsorSaveStatus('Not saved');throw error;}
  return true;
 }
 if(action==='sponsor-review-field'){
  const title=sponsorFramingFieldLabels[id];if(!title)throw Error('Choose a Business Intent field to review.');
  const form=$('#sponsor-editor'),input=form?.querySelector(`[name="${id}"]`),composer=$('#sponsor-framing-message');
  if(!input||!composer)throw Error('Open Business Intent to prepare this field for review.');
  const text=String(input.value||'').trim();if(!text)throw Error('Add content to this field before reviewing it.');
  const passage='Review the '+title+' field:\n'+text;
  const key=sponsorReviewerKey(),previous=sponsorPreparedReviews.get(key),draft=sponsorReviewerCapture(composer);
  const prepared=draft.includes(passage)?draft:previous&&draft.includes(previous)?draft.replace(previous,passage):draft.trim()?draft+'\n\n'+passage:passage;
  sponsorPreparedReviews.set(key,passage);sponsorReviewerWrite(prepared);
  composer.value=prepared;composer.focus({preventScroll:true});composer.setSelectionRange?.(0,0);
  const status=origin?.closest('[data-framing-field]')?.querySelector('.sponsor-field-save-status');
  if(status)status.textContent='Added to AI partner';
  return true;
 }
 if(action==='sponsor-framing-save'){
  await saveSponsorDraft();
  const status=origin?.closest('[data-framing-field]')?.querySelector('.sponsor-field-save-status');
  if(status){status.textContent='Saved';status.style.animation='none';void status.offsetWidth;status.style.animation='';}
  return true;
 }
 if(action==='sponsor-save'){await saveSponsorDraft();render();return true;}
 if(action==='sponsor-role-remove'||action==='sponsor-role-add'){
  const data=sponsorFormData();let a=data.answers.q4;if(action==='sponsor-role-add')a.roles.push({name:'',does:'',needs:'',where:'',often:''});else a.roles.splice(Number(id),1);
  a.completed=false;a.confirmed=false;await command('sponsor-save',{expected:state.intake.draft.ref,answers:{q4:a}});pageDirty=false;await load();render();return true;
 }
 await saveBeforeProjectChange();
 if(action==='sponsor-setup-draft'){
  if(state.actor!=='priya'||!state.intake?.draft)throw Error('The saved setup draft is private to the business sponsor.');
  setupDraftPreviewProject=`${state.actor}:${state.project.id}:${state.project.version}`;
  view='planning';selected=null;intakeCaseId=null;render();
  const heading=document.querySelector('#main h1');if(heading)heading.focus();
 }
 else if(action==='sponsor-resource'){sponsorResources=id==='documents'?'documents':'questions';render();}
 else if(action==='sponsor-step'){if($('#modal')?.classList.contains('navigation-dialog'))closeModal();intakeCaseId=null;sponsorStage=id;view=id==='planning'?(state.intake.setup_governance?.enabled&&!state.intake.setup_governance.editable?'requirements':'planning'):'intent';setupDraftPreviewProject=null;intakeStep=id==='review'?'review':id==='brief'?'context':'rationale';selected=null;render();}
 else if(action==='sponsor-validation'){intakeCaseId=null;sponsorValidation=id;sponsorFit=false;sponsorStage='brief';view='intent';intakeStep='context';render();}
 else if(action==='sponsor-question'){intakeCaseId=null;sponsorQuestion=id;sponsorFit=false;sponsorValidation=null;sponsorStage='brief';view='intent';intakeStep='context';render();}
 else if(action==='sponsor-fit'){sponsorFit=true;sponsorValidation=null;sponsorStage='brief';view='intent';intakeStep='value';render();}
 else if(action==='sponsor-accept-value'){
  modal('Review the working value proposition',valueFitSnapshot(state.intake.draft.body.values)+valuePreview(state.intake.draft.body.values)+'<p>This records your reviewed starting hypothesis, not evidence validation or financial approval.</p>','Record review',async()=>command('intake-accept-value',{expected:state.intake.draft.ref,confirm:true,rationale:'Sponsor reviewed the complete value fit in the adapted sponsor workflow.'}));
 }else if(action==='sponsor-share'){
  modal('Share Business Intent',`<p>Research and Design will receive the exact saved Business Intent, value proposition, goals, measures and requirements. Private documents and other AI partner conversations stay private.</p>${typeof businessAssessmentReleaseChoice==='function'?businessAssessmentReleaseChoice():''}<label class="checkbox"><input name="confirm" type="checkbox" required>I have reviewed this version and authorize sharing it for direction review.</label>`,'Share for review',async fd=>{
   const assessment=typeof businessAssessmentSelectedRelease==='function'?businessAssessmentSelectedRelease(fd):null;
   const p=await command('intake-preflight',{expected:state.intake.draft.ref,...(assessment?{business_assessment:assessment}:{}),research_focus:state.intake.draft.body.values.research_question,design_focus:state.intake.draft.body.values.operations_question,open_questions:state.intake.draft.body.values.open_questions});await load();const prepared=state.intake.preflight.packages.find(x=>x.ref.id===p.id);
   return command('intake-request',{expected:state.intake.draft.ref,preflight:prepared.ref,confirm:fd.get('confirm')==='on',...(assessment?{release_business_assessment:true}:{})});
  });
 }else if(action==='sponsor-use-advice'){const q=sponsorQuestion,r=coachInfo().runs.find(r=>r.ref.id===id),proposal=r.body.output.suggestions[0];modal('Use this suggested response',sponsorText('edited_text','Proposed response',proposal.text,'Review and edit before saving. The response stays private until you share Business Intent.',7),'Use in draft',fd=>command('sponsor-apply-advice',{expected:state.intake.draft.ref,question:q,run_id:id,edited_text:fd.get('edited_text'),confirm:true}));}
 else if(action==='sponsor-coach'){
  if(!coachInfo().model.configured){modelSetup();return true;}
  const message=sponsorReviewerCapture($('#sponsor-coach-message'));
  if(!message.trim())throw Error('Enter a question for your AI partner.');
  modal('Ask your AI partner',`<p>The saved response, project intake and your question will be sent to the configured model. No source documents are selected. Advice does not change your answers.</p>`,'Ask',async()=>{
   const r=await command('sponsor-coach',{expected:state.intake.draft.ref,question:id,message,consent:true});sponsorCoachResult={id:r.ref.id,question:id};return r;
  });
 }else if(action==='sponsor-ask'){
  if(!coachInfo().model.configured){modelSetup();return true;}
  const message=sponsorReviewerCapture($('#sponsor-framing-message')||$('#sponsor-coach-message'));
  if(!message.trim())throw Error('Enter a question for your AI partner.');
  const sources=coachInfo().sources.map(s=>s.ref);
  modal('Ask your AI partner',`<p>Your question, saved Business Intent and selected documents will be sent to the configured model. The response is advice, without a rating. It does not change answers or publish anything.</p>${para(message)}<p class="caption">Include up to ten documents.</p>${coachInfo().sources.map((source,i)=>`<label class="checkbox"><input name="source" type="checkbox" value="${esc(source.ref.id)}" ${i<10?'checked':''}>${esc(source.body.title)}</label>`).join('')}`,'Ask',async fd=>command('intake-coach',{expected:state.intake.draft.ref,skill:'review-value',field:'value',message,sources:fd.getAll('source').map(id=>sources.find(source=>source.id===id)),consent:true}));
 }else if(action==='sponsor-analyze'){
  if(!coachInfo().model.configured){modelSetup();return true;}
  const sources=coachInfo().sources.map(s=>s.ref);
  modal('Record Business Intent assessment',`<p>A whole-Business-Intent assessment uses two model requests: first freeze the material claims, then judge their reasoning and evidence under the shared standard. It saves a private, provisional assessment; it does not change answers or publish anything.</p><p class="caption">The saved Business Intent and selected documents will be sent to the configured model. Include up to ten documents.</p>${coachInfo().sources.map((source,i)=>`<label class="checkbox"><input name="source" type="checkbox" value="${esc(source.ref.id)}" ${i<10?'checked':''}>${esc(source.body.title)}</label>`).join('')}`,'Record assessment',async fd=>command('intake-coach',{expected:state.intake.draft.ref,skill:'assess-business',field:'value',message:'Assess the exact saved business argument, material claims and requirement starting definitions. Preserve uncertainty, counterevidence and applicability limits.',sources:fd.getAll('source').map(id=>sources.find(source=>source.id===id)),consent:true}));
 }
 return true;
}
document.addEventListener('input',e=>{
 if(['sponsor-framing-message','sponsor-coach-message'].includes(e.target.id)){if(typeof reviewerDraftWrite!=='function')sponsorReviewerWrite(e.target.value);return;}
 if(e.target.closest('#sponsor-editor')?.dataset.kind==='framing'){
  pageDirty=true;
  const field=e.target.closest('[data-framing-field]'),checkbox=field?.querySelector('[data-framing-complete]');
  const status=field?.querySelector('.sponsor-field-save-status');if(status)status.textContent='';
  if(checkbox&&e.target!==checkbox)checkbox.checked=false;
  document.querySelectorAll('#sponsor-editor [data-framing-field]').forEach(el=>{const control=el.querySelector('textarea,input:not([type=checkbox])'),complete=el.querySelector('[data-framing-complete]');if(complete)complete.disabled=!control?.value.trim();});
  sponsorSaveStatus('Unsaved edits');return;
 }
 if(e.target.closest('#sponsor-editor')){pageDirty=true;const completed=$('#sponsor-editor [name=completed]');if(completed&&e.target!==completed)completed.checked=false;sponsorSyncQuestionProgress(true);sponsorSaveStatus('Unsaved edits');}});
async function sponsorUploadFile(file){
 try{await saveSponsorDraft();if(file.size>5*1024*1024)throw Error('Choose a document under 5 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=8192)text+=String.fromCharCode(...bytes.subarray(i,i+8192));await command('intake-source',{filename:file.name,content:btoa(text),role:'background'});await load();render();toast('Document saved locally. Request analysis when ready.');}catch(error){toast(error.message);}
}
document.addEventListener('change',async e=>{
 if(e.target.closest('#sponsor-editor'))pageDirty=true;
 if(e.target.id==='sponsor-upload'&&e.target.files[0])await sponsorUploadFile(e.target.files[0]);
});
document.addEventListener('dragover',e=>{const drop=e.target.closest('.sponsor-dropzone');if(drop){e.preventDefault();drop.classList.add('is-dragging');}});
document.addEventListener('dragleave',e=>{const drop=e.target.closest('.sponsor-dropzone');if(drop&&!drop.contains(e.relatedTarget))drop.classList.remove('is-dragging');});
document.addEventListener('drop',async e=>{const drop=e.target.closest('.sponsor-dropzone');if(!drop)return;e.preventDefault();drop.classList.remove('is-dragging');if(e.dataTransfer.files.length!==1){toast('Choose one document at a time.');return;}await sponsorUploadFile(e.dataTransfer.files[0]);});

function openSponsorAnalysis(id){const run=coachInfo().runs.find(x=>x.ref.id===id);if(!run)return;modal('Suggested starting answers',para(run.body.output.reply)+(run.body.output.suggestions||[]).map(s=>`<section class="rule">${val(intakeNames[s.field]||s.field,s.text)}${citationsHtml(s.citations||[])}${button('Review this wording','coach-apply',run.ref.id+'|'+s.field)}</section>`).join(''));}
function sponsorSharedSnapshot(b){const brief=b.sponsor_brief;return `<section class="card accent"><h2>${esc(b.title)}</h2><p class="caption">Shared Business Intent · saved snapshot</p>${val('Problem statement',brief.framing.statement)}${['problem','solution','risk','options'].map(k=>val(({problem:'Problem',solution:'Proposed approach',risk:'Risks',options:'Options'})[k],brief.framing.summary[k])).join('')}</section><section class="card section"><h2>Business context</h2>${(state.sponsor?.questions||sponsorQuestionCatalog).map(q=>`<details><summary>${esc(q.title)}</summary>${q.kind==='roles'?(brief.answers[q.id]?.roles||[]).map(sponsorRoleRead).join(''):para((brief.answers[q.id]?.items||[]).join('\n'))}</details>`).join('')}</section><section class="card section"><h2>Value proposition & investment</h2>${valueFitSnapshot(b.values)}${valuePreview(b.values)}${val('Investment case',b.values.investment_case)}</section>${typeof businessAssessmentSharedRead==='function'?businessAssessmentSharedRead(b.business_assessment):''}${goalsRead(b.goal_snapshot)}<section class="card section"><h2>Requirements</h2>${b.scaffold.map(d=>`<details><summary>${esc(d.label)}</summary>${areaRead(d,b.goal_snapshot)}${(d.children||[]).map(c=>areaRead(c,b.goal_snapshot)).join('')}</details>`).join('')}</section>`;}

const sponsorQuestionCatalog=[{"id": "q2", "section": "Project Goals", "title": "Problems to solve", "kind": "list", "hint": "One problem per line", "prompt": "Which problems must this project solve to be worth doing?", "consider": ["Name the problem, then its cost.", "Keep solutions out of this answer."]}, {"id": "q3", "section": "Project Goals", "title": "Outcomes", "kind": "list", "hint": "3–5 outcomes", "prompt": "If this project works, what will be different for the people involved?", "consider": ["Describe outcomes, not features.", "Who notices first when it’s working? Metrics come later in Measuring Success."]}, {"id": "q4", "section": "Users", "title": "Define users", "kind": "roles", "hint": "One card per user or role", "prompt": "Who uses, operates, approves or is affected by this system, including customers where relevant?", "consider": ["Who uses, operates or is affected by the system, and what do they do in their job?", "What event, request or information prompts each person to act?", "What do they do next, and what information or action do they pass on to someone else?", "What feedback tells them their action was received or the work is complete?"]}, {"id": "q5", "section": "Current Process", "title": "Current process", "kind": "list", "hint": "Steps in order", "prompt": "Walk through how the work happens today, step by step.", "consider": ["List steps in order; this becomes input to a process flow.", "Name who acts at each step."]}, {"id": "q6", "section": "Current Process", "title": "Pain points", "kind": "list", "hint": "Broken, slow, risky or missing", "prompt": "What is not working today, and where in the process does it break down?", "consider": ["One pain point per line.", "Approximate is fine; this is an area Research will investigate."]}, {"id": "q7", "section": "Evidence", "title": "Formal evidence", "kind": "list", "hint": "Data, audits, reports", "prompt": "What data, audits or reports show this problem is real?", "consider": ["Prefer numbers and named sources.", "Much of this may come from your uploaded documents."]}, {"id": "q8", "section": "Evidence", "title": "Informal evidence", "kind": "list", "hint": "Quotes or themes", "prompt": "What do the people involved, staff and leaders say about the current process?", "consider": ["Use real quotes where you have them."]}, {"id": "q9", "section": "Expected Outcomes & Behaviors", "title": "Future state process", "kind": "list", "hint": "Steps in order", "prompt": "How should the work happen once this succeeds?", "consider": ["Mirror the current process steps so the difference is clear."]}, {"id": "q10", "section": "Expected Outcomes & Behaviors", "title": "Project must-haves", "kind": "list", "hint": "Observable behaviors", "prompt": "What must the system always do?", "consider": ["Write as observable behavior."]}, {"id": "q11", "section": "Uncertainty & Edge Cases", "title": "Unclear or uncertain scenarios", "kind": "list", "hint": "When information isn’t clear", "prompt": "What should happen when a request does not have enough information to act on?", "consider": ["Who asks for more detail, and how?"]}, {"id": "q12", "section": "Uncertainty & Edge Cases", "title": "Fallbacks", "kind": "list", "hint": "Unclear ownership, missing path, or failure", "prompt": "Which kinds of failure need a fallback, and who is responsible for each?", "consider": ["Use existing answers and decisions first. Clarify only what remains unresolved.", "If ownership is unclear: where should the item go, and who acknowledges responsibility?", "If the path is known but not available: what happens next, and who owns the item?", "If a technical step fails: what must be retained, retried and communicated?", "Undecided is valid: name an owner and the next check. Operations and engineering can refine the recovery details."]}, {"id": "q13", "section": "Uncertainty & Edge Cases", "title": "Edge cases", "kind": "list", "hint": "Unusual situations", "prompt": "What unusual situations must the system handle?", "consider": ["Duplicates, missing details, requests that span teams or locations."]}, {"id": "q14", "section": "Scope", "title": "In scope", "kind": "list", "hint": "What we will build", "prompt": "What is definitely included in this first release?", "consider": ["Name capabilities, not screens."]}, {"id": "q15", "section": "Scope", "title": "Out of scope", "kind": "list", "hint": "What we won’t do", "prompt": "What is explicitly excluded?", "consider": ["Exclusions prevent scope creep later.", "Carry forward existing scope decisions and their sources. Revisit only an unresolved boundary, a relevant change, or an authority conflict."]}, {"id": "q16", "section": "Scope", "title": "Unknown", "kind": "list", "hint": "Open boundaries", "prompt": "Which boundaries are still undecided?", "consider": ["Flag them now so Research can help resolve them.", "Carry forward existing scope decisions and their sources. Revisit only an unresolved boundary, a relevant change, or an authority conflict."]}, {"id": "q17", "section": "Measuring Success", "title": "Success metrics", "kind": "list", "hint": "Baseline and target", "prompt": "Which measures, with today’s baseline and a target, define success?", "consider": ["Tie each target to a baseline."]}, {"id": "q18", "section": "Measuring Success", "title": "Measurement cadence", "kind": "list", "hint": "When to check", "prompt": "How often, and where, will these measures be reviewed?", "consider": ["Name the data source and the forum."]}, {"id": "q19", "section": "Constraints & Limits", "title": "Operational limits", "kind": "list", "hint": "Operating conditions", "prompt": "What operational conditions must the solution work within?", "consider": ["Devices, connectivity, shift patterns, labor agreements."]}, {"id": "q20", "section": "Constraints & Limits", "title": "Project limits", "kind": "list", "hint": "Rules that can’t be broken", "prompt": "Which project rules can never be broken?", "consider": ["Policy, security, budget and timeline."]}, {"id": "q21", "section": "Risks & Dependencies", "title": "Project risks", "kind": "list", "hint": "What could go wrong", "prompt": "What could stop this project from succeeding?", "consider": ["Adoption, data quality, ownership."]}, {"id": "q22", "section": "Risks & Dependencies", "title": "Dependencies", "kind": "list", "hint": "Teams and systems", "prompt": "What teams or systems does this depend on?", "consider": ["Include the software delivery team here."]}, {"id": "q23", "section": "Risks & Dependencies", "title": "Additional stakeholders", "kind": "list", "hint": "Operational or not", "prompt": "Who else has a stake in this, including non-operational groups?", "consider": ["Finance, Legal, Labor Relations, Corporate Communications."]}];

Object.assign(intakeNames,Object.fromEntries(sponsorQuestionCatalog.map(q=>[{'q2': 'business_problems', 'q3': 'desired_outcomes', 'q4': 'user_roles', 'q5': 'current_process', 'q6': 'pain_points', 'q7': 'formal_evidence', 'q8': 'informal_evidence', 'q9': 'future_process', 'q10': 'must_haves', 'q11': 'uncertain_scenarios', 'q12': 'fallbacks', 'q13': 'edge_cases', 'q14': 'in_scope', 'q15': 'out_scope', 'q16': 'scope_unknowns', 'q17': 'measures', 'q18': 'measure_review', 'q19': 'operating_limits', 'q20': 'project_limits', 'q21': 'project_risks', 'q22': 'dependencies', 'q23': 'stakeholders'}[q.id],q.title])));

