let sponsorResources='questions';
function sponsorFlowActive(){return state.actor==='priya'&&!!state.sponsor&&(view==='planning'||view==='intent'&&intakeStep!=='learning'&&!intakeCaseId);}
function sponsorWorkspaceBar(){return `<div class="sponsor-workspace-band"><div class="sponsor-breadcrumb"><nav aria-label="Breadcrumb">${button('Home','projects-home','','quiet')}<span aria-hidden="true">›</span>${button('Projects','projects','','quiet sponsor-current-project')}</nav></div></div>`;}
function sponsorMeter(title,n,total){return `<div class="sponsor-meter"><span>${title}</span><div><strong>${n}</strong><span> / ${total}</span></div><meter min="0" max="${total}" value="${n}" aria-label="${title}">${n} of ${total}</meter></div>`;}
function sponsorHeading(title,desc,stage,actions=''){
 const n=sponsorSteps.findIndex(([id])=>id===stage)+1;
 return `<div class="sponsor-heading"><div><div class="eyebrow">Step ${n} of ${sponsorSteps.length}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${actions?`<div class="sponsor-heading-actions">${actions}</div>`:''}</div>`;
}
function sponsorGuidance(stage){const copy={
 framing:['A clear business question helps teams investigate value without assuming the proposed solution is right.','Add relevant documents and save your starting direction. Use Review this field to prepare a question for your AI partner; analysis starts only when you choose it.','Context connects people, work, evidence, scope and measures. Unknowns can remain explicit.'],
 brief:['Context gives Research and Design a useful question and context for their Working briefs.','Save what you know, distinguish assumptions and leave unresolved questions visible. Complete is a personal progress marker, not validation or publication.','Review the initial requirements setup, or return to Review & publish after setup has been published. Later baseline changes go through Decisions & Issues.'],
 planning:['The build needs a clear connection from business value to what must be true.','Review the goals and KPIs, then open each requirement category to refine its sub-drawers and acceptance criteria.','Review & publish, where you inspect the full Business Intent and exact package before sharing.'],
 review:['Teams need the exact direction, evidence limits and questions they are being asked to investigate.','Inspect the saved content and selected package, obtain the existing direction reviews, then deliberately publish. A model suggestion or completed answer does not publish anything.','Research and Design develop private Working briefs and publish selected Outcomes reports. Consequential findings can return to the sponsor through Decisions & Issues.']
 }[stage];return `<details class="sponsor-guidance" aria-label="About this step"><summary>About this step</summary><div class="sponsor-guidance-content">${copy.map((t,i)=>`<div><strong>${['Why this step','What to do','What comes next'][i]}</strong><p>${t}</p></div>`).join('')}</div></details>`;}
function sponsorRoleRead(role){
 const fields=[['What they do','does'],['What they need','needs'],['Where / when','where'],['How often','often']];
 return `<details class="sponsor-role-profile"><summary><span class="sponsor-role-profile-name">${esc(role.name||'Unnamed user or role')}</span><span class="sponsor-role-profile-preview">${esc(role.does||'No work description supplied.')}</span></summary><dl>${fields.map(([title,key])=>`<div><dt>${title}</dt><dd class="pre">${esc(role[key]||'Not supplied')}</dd></div>`).join('')}</dl></details>`;
}
function sponsorAnswerStatus(a){const status=sponsorAnswerState(a);return `${a?.ai&&sponsorAnswerHas(a)?`<span class="ac-state ac-state-suggested" title="Filled in for you. Edit or save it to make it yours; it does not count until then.">Suggested · ${esc(a.origin||'AI partner')}</span> `:''}<span class="workbench-context-chip${status==='Not started'?'':' workbench-context-chip-progress'} sponsor-answer-status" title="Personal answer progress. Completion does not publish, validate or approve the content.">Status: ${esc(status)}</span>`;}
function sponsorCoreRead(f,v){return `<div class="sponsor-core-summary">${val('Summary',v.value||'Not drafted yet.')}${val('Problem',f.statement)}${val('Solution',f.summary.solution)}${val('Benefits',v.gains)}${val('Why now',v.why_now)}</div>`;}
function sponsorFramingOutput(){
 const assessment=typeof businessAssessmentPanel==='function'?businessAssessmentPanel():'',recorded=assessment?`<details class="sponsor-recorded-assessment"><summary>Recorded assessment</summary>${assessment}</details>`:'',runs=coachInfo().runs.filter(r=>['seed-value','review-value'].includes(r.body.skill)),run=runs.at(-1);if(!run)return recorded;
 const current=JSON.stringify(run.body.basis)===JSON.stringify(state.intake.draft.ref);
 return `<section class="sponsor-framing-feedback">${current?'':'<p class="caption">Earlier review · saved content may have changed</p>'}${run.body.user_message?`<div class="reviewer-user-message"><p class="reviewer-speaker">You</p>${para(run.body.user_message)}</div>`:''}<h3 class="reviewer-speaker">AI partner</h3>${para(run.body.output.reply)}${(run.body.output.suggestions||[]).map(s=>coachSuggestion(run,s)).join('')}${(run.body.output.questions||[]).map(q=>para(q.question)).join('')}${runs.length>1?`<details><summary>Earlier feedback (${runs.length-1})</summary>${runs.slice(0,-1).reverse().map(r=>para(r.body.output.reply)).join('')}</details>`:''}</section>`+recorded;
}
const sponsorFramingFieldLabels={name:'Project name',context:'Additional context',statement:'Problem','fit-value':'Summary','fit-gains':'Benefits','fit-why_now':'Why now','summary-problem':'Supporting problem notes','summary-solution':'Solution','summary-risk':'Risks','summary-options':'Options'};
function sponsorFramingFieldActions(name){return `<span class="sponsor-field-save-status" role="status" aria-live="polite"></span>${button('Save','sponsor-framing-save',name,'quiet small')}${name==='name'?'':button('Review this field','sponsor-review-field',name,'quiet small')}`;}

function sponsorValueField(name,title,value='',help='',rows=4){const id='sponsor-core-'+name;return `<div class="sponsor-edit-block sponsor-value-field" data-framing-field="${esc(name)}"><label class="sponsor-value-label" for="${esc(id)}">${esc(title)}</label><p class="sponsor-value-description" id="${esc(id)}-hint">${esc(help)}</p><textarea id="${esc(id)}" name="${esc(name)}" aria-describedby="${esc(id)}-hint" rows="${rows}" maxlength="20000">${esc(value)}</textarea><div class="sponsor-framing-field-actions workbench-review-actions">${sponsorFramingFieldActions(name)}</div></div>`;}
function sponsorFraming(){
 const f=sponsorInfo().brief.framing,v=state.intake.draft.body.values,sources=coachInfo().sources||[];
 const resources=`<aside class="sponsor-panel sponsor-framing-resources" aria-label="Business Intent documents"><div class="sponsor-panel-head"><h2>Documents</h2></div><div class="sponsor-panel-body"><div class="sponsor-dropzone"><span class="sponsor-upload-icon" aria-hidden="true">↑</span><strong>Drop files or browse</strong><p>PDF, DOCX, PPTX, TXT or CSV · up to 5 MB each</p><label class="sponsor-upload-label">Browse files<input id="sponsor-upload" type="file" accept=".pdf,.docx,.pptx,.txt,.md,.csv,.json" aria-label="Upload project document"></label></div><div class="sponsor-documents">${sources.map(s=>`<div class="sponsor-file"><a href="#main" class="document-name-link" data-action="coach-read-source" data-id="${esc(s.ref.id)}">${esc(s.body.title)}</a></div>`).join('')||'<p class="caption">No documents uploaded yet.</p>'}</div>${projectConnectionShortcuts()}</div></aside>`;
 const editor=`<form id="sponsor-editor" data-kind="framing" class="sponsor-panel sponsor-framing-editor"><div class="sponsor-error" role="alert"></div><div class="sponsor-panel-body"><h2>Core Value Statement</h2><div class="sponsor-value-field" data-framing-field="name"><label class="sponsor-field"><span>Project name</span><input name="name" maxlength="200" value="${esc(f.name)}" required></label><div class="sponsor-framing-field-actions workbench-review-actions">${sponsorFramingFieldActions('name')}</div></div>${sponsorValueField('fit-value','Summary',v.value,'State who benefits, the need being met and the value the offering creates.')}<div class="sponsor-core-fields">${sponsorValueField('statement','Problem',f.statement,'Describe the unmet need, who is affected and the consequence today.')}${sponsorValueField('summary-solution','Solution',f.summary.solution,'Explain the proposed approach and how it addresses the need.')}${sponsorValueField('fit-gains','Benefits',v.gains,'Describe the improvements users and the business should experience.')}${sponsorValueField('fit-why_now','Why now',v.why_now,'Explain what makes this a priority and the cost or risk of waiting.')}</div>${sponsorValueField('context','Additional context',f.context,'Optional · add anything your documents did not capture.')}<details class="sponsor-retained"><summary>Supporting problem notes, risks & alternatives</summary><div class="sponsor-supporting-fields">${sponsorValueField('summary-problem','Supporting problem notes',f.summary.problem,'Add evidence, examples or detail that strengthens the problem statement.')}${sponsorValueField('summary-risk','Risks',f.summary.risk,'Identify what could prevent the proposed value from being achieved.')}${sponsorValueField('summary-options','Options',f.summary.options,'Describe other ways to meet the need, including improving the current approach.')}</div></details><div class="sponsor-actions">${button('Save draft','sponsor-save','','primary')}</div><span id="sponsor-save-status" role="status" aria-live="polite" data-save-state="saved" class="caption">Draft saved</span></div></form>`;
 const rail=`<aside class="sponsor-panel sponsor-coach sponsor-framing-review" aria-label="AI partner"><div class="sponsor-coach-title"><div><h2 class="thought-partner-title">AI partner</h2><span class="caption">Business Intent</span></div></div><div class="sponsor-coach-body"><div class="sponsor-coach-log">${sponsorFramingOutput()}</div>${sponsorReviewerComposer('sponsor-framing-message','sponsor-ask')}${button('Record assessment','sponsor-analyze','','quiet small')}${coachInfo().model.configured?'':'<p class="caption sponsor-model-guidance">Your AI partner is unavailable. You can keep drafting.</p>'}</div></aside>`;
 return sponsorHeading('Business Intent','The promise and its proof: Core Value Statement, goals and success measures.','framing')+`<div class="sponsor-framing-step-row">${sponsorGuidance('framing')}${button('Context →','sponsor-step','brief','quiet')}</div>`+`<div class="sponsor-framing-grid">${resources}<div class="sponsor-framing-main">${editor}${typeof sponsorGoalsPanel==='function'?sponsorGoalsPanel():''}</div>${rail}</div>`;
}
function sponsorAnswerState(a){return !sponsorAnswerHas(a)?'Not started':a.completed?'Completed':'Started';}
function sponsorStateMark(a){const status=sponsorAnswerState(a);return `<span class="sponsor-state ${status==='Completed'?'is-complete':status==='Started'?'is-started':''}" role="img" aria-label="${status}" title="${status}"></span>`;}
function sponsorSyncQuestionProgress(unsaved=false){
 const form=$('#sponsor-editor');if(form?.dataset.kind!=='answer')return;
 const id=form.dataset.question,answer=sponsorFormData().answers[id];
 if(unsaved)answer.completed=false;
 const mark=sponsorStateMark(answer),checkbox=$('#sponsor-editor [name=completed]');
 if(checkbox)checkbox.disabled=!sponsorAnswerHas(answer);
 document.querySelectorAll(`[data-action="sponsor-question"][data-id="${id}"] .sponsor-state`).forEach(el=>{el.outerHTML=mark;});
 const progress=document.querySelector('.sponsor-heading-actions');if(progress)progress.innerHTML=sponsorProgress({id,answer});
}
function sponsorSectionTitle(title){return title==='Project Goals'?'Product Goals':title;}
function sponsorQuestionTitle(q){return q.id==='q6'?'Where the process fails':q.id==='q9'?'Future state':q.title;}
function sponsorProgress(edit=null){const s=sponsorInfo();return sponsorMeter('Completed',s.questions.filter(q=>sponsorAnswerState(edit?.id===q.id?edit.answer:s.brief.answers[q.id])==='Completed').length,s.questions.length);}
// Where the intent stands before sharing. Built only from saved state; no model call and no readiness score.
function sponsorPublishSummary(s){
 const total=s.questions.length,answered=s.questions.filter(q=>sponsorAnswerHas(s.brief.answers[q.id])).length;
 const g=state.goals||{},goals=(g.goals||[]).length,measures=g.measures||[],targets=measures.filter(m=>String((m.target??m.body?.target)||'').trim()).length;
 const drawers=(state.records||[]).filter(r=>r.kind==='requirement-drawer'&&!String(r.ref.id).slice(4).includes('/')&&r.body?.status!=='withdrawn'&&r.body?.included!==false);
 const areas=new Set(drawers.map(r=>r.ref.id)).size;
 const a=typeof businessAssessmentCurrent==='function'?businessAssessmentCurrent():null,out=a?.body?.output;
 const cell=(cls,title,body,note)=>`<div class="publish-summary-cell ${cls}"><dt>${esc(title)}</dt><dd>${esc(body)}</dd>${note?`<p class="caption">${esc(note)}</p>`:''}</div>`;
 return `<section class="sponsor-panel publish-summary" aria-labelledby="publish-summary-title"><h2 id="publish-summary-title">Where this stands before you share</h2><dl>
 ${cell(answered===total?'is-ok':'is-open','Your answers',`${answered} of ${total}`,answered===total?'':`${total-answered} still open`)}
 ${cell(measures.length&&targets===measures.length?'is-ok':'is-open','Goals and measures',`${goals} goal${goals===1?'':'s'} · ${measures.length} measure${measures.length===1?'':'s'}`,measures.length?`${targets} of ${measures.length} with a target`:'No measures yet')}
 ${cell(areas?'is-ok':'is-open','Requirement areas',areas?`${areas} set up`:'None set up','Teams fill these with evidence after you share')}
 ${cell(!out?'':!a.stale?.length?'is-ok':'is-open','AI partner assessment',out?`Confidence: ${businessAssessmentLevel(out.confidence?.level)}`:'Not run',out?(a.stale?.length?'Saved before your latest changes; run it again to refresh':String(out.summary||'').slice(0,140)):'Optional. Run it from Business Intent to see weak spots first.')}
 </dl></section>`;
}
function sponsorQuestionNav(q,answers,sections){const sources=coachInfo().sources||[];return `<aside class="sponsor-resources sponsor-panel"><div class="sponsor-resource-tabs" role="group" aria-label="Context resources"><button type="button" data-action="sponsor-resource" data-id="questions" aria-pressed="${sponsorResources==='questions'}">Questions</button><button type="button" data-action="sponsor-resource" data-id="documents" aria-pressed="${sponsorResources==='documents'}">Documents <span>${sources.length}</span></button></div>${sponsorResources==='documents'?`<div class="sponsor-panel-head"><h2>Incoming documents</h2></div><div class="sponsor-resource-docs">${sources.map(s=>`<div><a href="#main" class="document-name-link" data-action="coach-read-source" data-id="${esc(s.ref.id)}">${esc(s.body.title)}</a></div>`).join('')||'<p class="caption">Add documents in Business Intent.</p>'}</div><section class="workbench-created-documents" aria-label="Created here"><h3>Created here</h3><a href="#main" class="workbench-document-link" data-action="sponsor-step" data-id="review">Business Intent</a><p class="caption">Working document</p></section>`:`<nav class="sponsor-qnav" aria-label="Context questions"><div class="sponsor-panel-head"><h2>Questions</h2><span>Q2–Q23</span></div><div class="sponsor-qnav-scroll">${sections.map(title=>{const qs=sponsorInfo().questions.filter(x=>x.section===title);return `<div class="sponsor-qsection"><div class="sponsor-qsection-title"><span>${esc(sponsorSectionTitle(title))}</span></div>${qs.map(x=>`<button type="button" data-action="sponsor-question" data-id="${x.id}" ${q.id===x.id&&!sponsorFit&&!sponsorValidation?'aria-current="true"':''}><span>${x.id.toUpperCase()}</span><span class="sponsor-qtitle">${esc(sponsorQuestionTitle(x))}</span>${sponsorStateMark(answers[x.id])}</button>`).join('')}</div>`;}).join('')}${typeof contextValidationNav==='function'?contextValidationNav(sponsorValidation):''}</div><div class="sponsor-legend"><span><i class="sponsor-state" aria-hidden="true"></i>Not started</span><span><i class="sponsor-state is-started" aria-hidden="true"></i>Started</span><span><i class="sponsor-state is-complete" aria-hidden="true"></i>Completed</span></div></nav>`}</aside>`;}
function sponsorListItem(text,index){return `<div class="sponsor-list-item"><span class="sponsor-item-number">${index+1}</span><label class="sponsor-field"><span class="sr-only">Answer item ${index+1}</span><textarea name="answer" rows="3" maxlength="20000" placeholder="Add an item">${esc(text)}</textarea></label><button type="button" class="quiet small remove-control" data-action="sponsor-item-remove" aria-label="Remove answer item ${index+1}" title="Remove answer item ${index+1}"><span aria-hidden="true">×</span></button></div>`;}
function sponsorListEditor(a){return `<div id="sponsor-answer-items">${(a.items.length?a.items:['']).map(sponsorListItem).join('')}</div>${button('Add item','sponsor-item-add','','quiet small')}`;}
function sponsorNextStep(){return state.intake?.setup_governance?.enabled&&!state.intake.setup_governance.editable?{label:'Review & publish →',stage:'review'}:{label:'Requirements set up →',stage:'planning'};}
function sponsorBrief(){
 const s=sponsorInfo(),questions=s.questions,answers=s.brief.answers,q=questions.find(x=>x.id===sponsorQuestion)||questions[0],a=answers[q.id],sections=[...new Set(questions.map(q=>q.section))],v=state.intake.draft.body.values;
 const editor=sponsorValidation&&typeof contextValidationEditor==='function'?contextValidationEditor(sponsorValidation):sponsorFit?sponsorFitEditor():`<form id="sponsor-editor" data-kind="answer" data-question="${q.id}"><div class="sponsor-error" role="alert"></div><div class="sponsor-qmeta"><span class="sponsor-question-count">${q.id.toUpperCase()} of 23</span><span>${esc(sponsorSectionTitle(q.section))}</span></div><h2>${esc(sponsorQuestionTitle(q))}</h2>${typeof contextShapesLine==='function'?contextShapesLine(q):''}<div class="sponsor-consider"><strong>How to approach this</strong><ul>${q.consider.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>${q.kind==='roles'?'':`<div class="sponsor-answer-head"><span>${esc(q.hint)}</span></div>`}${q.kind==='roles'?sponsorRoles(a):sponsorListEditor(a)}<div class="sponsor-answer-footer"><div class="sponsor-actions">${button('Save draft','sponsor-save','','primary')}<label class="sponsor-complete"><input name="completed" type="checkbox" data-action="sponsor-complete" ${a.completed&&sponsorAnswerHas(a)?'checked':''} ${sponsorAnswerHas(a)?'':'disabled'}><span class="sponsor-complete-mark" aria-hidden="true">✓</span><span>Complete</span></label></div><span id="sponsor-save-status" role="status" aria-live="polite" data-save-state="saved" class="caption">Draft saved</span></div></form>`;
 const coach=sponsorValidation&&typeof contextValidationCoach==='function'?contextValidationCoach(sponsorValidation):sponsorFit?`<div class="sponsor-coach-title"><div><h2 class="thought-partner-title">AI partner</h2><span class="caption">Value proposition & investment</span></div></div><div class="sponsor-coach-body"><p class="sponsor-coach-bubble">Connect each job, pain and gain to the proposed response. The value proposition is the synthesis of that fit.</p><details><summary>Investment discipline</summary><p>Separate one-time costs from recurring run costs. State the benefit mechanism, baseline, timing, owner and uncertainty; avoid double-counting value.</p></details><p class="caption">Goals define the outcome. KPIs test the outcome. Acceptance criteria test product behavior.</p>${sponsorFramingOutput()}${sponsorReviewerComposer('sponsor-coach-message','sponsor-ask')}</div>`:`<div class="sponsor-coach-title"><div><h2 class="thought-partner-title">AI partner</h2></div></div><div class="sponsor-coach-body"><div class="sponsor-coach-log">${sponsorCoachResult?.question===q.id?sponsorCoachOutput():''}</div>${sponsorReviewerComposer('sponsor-coach-message','sponsor-coach',q.id)}<p class="caption sponsor-model-guidance">${coachInfo().model.configured?'Review suggestions before using them.':'Your AI partner is unavailable. You can keep drafting.'}</p></div>`;
 return sponsorHeading('Context','The operational reality that shapes the requirements, then what must be validated.','brief',sponsorProgress())+`<div class="sponsor-framing-step-row">${sponsorGuidance('brief')}${button(sponsorNextStep().label,'sponsor-step',sponsorNextStep().stage,'quiet small')}</div>`+`<div class="sponsor-intake-grid">${sponsorQuestionNav(q,answers,sections)}<div class="sponsor-question-work"><details class="sponsor-north-star"><summary><span><strong>Core Value Statement</strong></span><span class="sponsor-show-all"><span class="sponsor-expand-label">Show all</span><span class="sponsor-collapse-label">Show less</span></span></summary><div>${sponsorCoreRead(s.brief.framing,v)}</div></details><section class="sponsor-panel sponsor-answer">${editor}</section></div><aside class="sponsor-panel sponsor-coach" aria-label="AI partner">${coach}</aside></div>`;
}
function sponsorRoles(a){return `<div id="sponsor-role-cards">${a.roles.map((r,i)=>`<div class="sponsor-role" role="group" aria-labelledby="sponsor-role-title-${i}" data-role-index="${i}"><h3 class="sponsor-role-title" id="sponsor-role-title-${i}">Role ${i+1}${i===0?' <span class="sponsor-primary-role">(Primary)</span>':''}</h3><div class="sponsor-role-head">${sponsorText('role-'+i+'-name','User or role',r.name,'',2)}</div><div class="sponsor-role-grid">${['does','needs','where','often'].map(k=>sponsorText('role-'+i+'-'+k,({does:'What they do',needs:'What they need',where:'Where / when',often:'How often'})[k],r[k],'',2)).join('')}</div><div class="sponsor-role-actions">${button('Remove role '+(i+1),'sponsor-role-remove',String(i),'quiet small')}</div></div>`).join('')}</div>${button(a.roles.length?'Add role':'Add a role card','sponsor-role-add','','quiet small')}`;}
function sponsorBriefStart(){
 const intent=records('intent')[0],b=intent?.body;
 return `<div class="sponsor-surface">${head('Business Intent','Define the problem, who benefits, the value offered and the investment case.')}<section class="sponsor-panel"><div class="sponsor-panel-body">${b?`<h2>Recorded Business Intent</h2>${ref(intent.ref)}${para(b.text)}${Object.entries(b.intake||{}).filter(([,v])=>typeof v==='string'&&v.trim()).length?`<details><summary>Saved business context</summary><div class="details-body">${Object.entries(b.intake||{}).filter(([,v])=>typeof v==='string'&&v.trim()).map(([k,v])=>val(intakeNames[k]||sponsorFitLabels[k]||k,v)).join('')}</div></details>`:''}`:'<h2>Start your Business Intent</h2>'}<p class="caption">No private sponsor draft has been created for this project. Creating one keeps the recorded intent, requirements and decisions intact.</p><form id="intake-start-form"><div class="error" role="alert"></div><div class="form-field"><label for="initiative-title">Initiative name</label><input id="initiative-title" name="title" required maxlength="20000" value="${esc(state.project.title)}"></div><button type="submit" class="primary">Create Business Intent</button></form></div></section></div>`;
}
function sponsorRequirementReference(record){
 const {body:b,ref:version}=record;
 return `<details class="planning-row" data-planning-detail="requirement-${esc(version.id)}">
  <summary><span><strong>${esc(b.title||b.text)}</strong></span><span class="caption">${esc(b.status||'Recorded')} · v${esc(version.revision)}</span></summary>
  <div class="planning-row-body">
   ${ref(version)}${sourceDetails(version)}${val('Requirement',b.text)}
   <h4>Acceptance criteria</h4>${b.acceptance_criteria?.trim()?criterionList(b.acceptance_criteria):'<p class="caption">No criteria recorded.</p>'}
   ${linkedGoalsRead(b)}${button('Open requirement','requirement',version.id,'quiet small')}
  </div></details>`;
}
function sponsorRequirements(){
 if(state.actor!=='priya')return requirements();
 const draft=state.intake.draft;
 const governance=state.intake.setup_governance;
 const readOnly=Boolean(governance?.enabled&&!governance.editable);
 const preview=readOnly&&setupDraftPreviewProject===`${state.actor}:${state.project.id}:${state.project.version}`;
 if(readOnly&&!preview)return requirements();
 const browseDrawers=!draft?.body.scaffold?.length;
 const plannedIds=new Set((browseDrawers?[]:scaffoldLeaves().flatMap(area=>requirementDrafts(area,area.key))).map(r=>r.id));
 const additional=browseDrawers?[]:records('requirement').filter(r=>!plannedIds.has(r.ref.id));
 const drawerContent=browseDrawers?`<section class="card planning-panel planning-drawers" aria-labelledby="planning-drawers-title">
  <h2 id="planning-drawers-title">Requirement drawers</h2>
  ${requirementDrawers({includeGoals:false})}
  ${records('requirement').map(sponsorRequirementReference).join('')}
  ${!draft?'<footer class="planning-editor-actions"><button type="button" data-nav="intent">Open Business Intent</button></footer>':''}
 </section>`:'';
 return `<div class="sponsor-surface sponsor-planning" data-planning-project="${esc(state.project.id)}:${esc(state.project.version)}">${head(preview?'Saved setup draft':'Requirements set up',preview?'Your retained private setup may differ from the published requirements. It remains read only; later changes go through Decisions & Issues.':'The business sponsor sets the starting goals, KPIs, requirement candidates and acceptance criteria for discovery. Shared versions and team input are available under Collaboration → Requirements.',preview?'<button type="button" data-nav="requirements">Back to Requirements</button>':'')}
  ${governance?.enabled?`<div class="banner blue setup-handoff"><p>${esc(governance.message)}</p>${governance.baseline?'<button type="button" data-nav="review">Open Decisions & Issues</button>':''}</div>`:''}
  ${draft?`<section class="planning-draft" aria-label="Requirement planning">${intakeDrawerForm({planning:true,readOnly})}</section>`:
   goalsRead({goals:records('goal'),measures:records('success-measure')},'Performance Indicators')}
  ${drawerContent}${additional.length?`<section class="card planning-panel section" aria-labelledby="additional-requirements-title"><h2 id="additional-requirements-title">Additional requirements</h2><p class="caption">These requirements have no matching draft in the current Business Intent.</p>${additional.map(sponsorRequirementReference).join('')}</section>`:''}</div>`;
}
function openPlanningField(id){
 const target=document.getElementById(id);
 if(!target)return;
 for(let parent=target;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;
 const focus=target.tagName==='DETAILS'?target.querySelector('summary'):target;
 focus.focus({preventScroll:true});
 focus.scrollIntoView({block:'nearest'});
}
function capturePlanningRows(){
 const page=document.querySelector('[data-planning-project]');
 if(!page)return null;
 return {project:page.dataset.planningProject,scroll:window.scrollY,
  open:new Set([...page.querySelectorAll('[data-planning-detail][open]')].map(el=>el.dataset.planningDetail))};
}
function restorePlanningRows(previous){
 const page=document.querySelector('[data-planning-project]');
 if(!page||page.dataset.planningProject!==previous.project)return false;
 for(const detail of page.querySelectorAll('[data-planning-detail]'))if(previous.open.has(detail.dataset.planningDetail))detail.open=true;
 window.scrollTo(0,previous.scroll);
 return true;
}
document.addEventListener('invalid',event=>{
 if(!event.target.closest('.sponsor-planning #intake-drawers-form'))return;
 for(let parent=event.target.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;
},true);
function sponsorReviewCoverage(s){const sections=[...new Set(s.questions.map(q=>q.section))],complete=s.questions.filter(q=>s.brief.answers[q.id]?.completed&&sponsorAnswerHas(s.brief.answers[q.id])).length;return `<details class="sponsor-panel sponsor-coverage"><summary class="sponsor-coverage-summary"><span>Response coverage</span><span>Marked complete ${complete} of ${s.questions.length}</span></summary><div class="sponsor-panel-body">${sponsorProgress()}<p class="caption">Completion means an answer is saved and checked; evidence gaps can remain open.</p>${sections.map(section=>{const qs=s.questions.filter(q=>q.section===section),n=qs.filter(q=>sponsorAnswerHas(s.brief.answers[q.id])).length;return `<div class="sponsor-section-meter"><span>${esc(sponsorSectionTitle(section))}</span><meter min="0" max="${qs.length}" value="${n}" aria-label="${esc(section)} answers">${n}/${qs.length}</meter><small>${n}/${qs.length}</small></div>`;}).join('')}</div></details>`;}
function sponsorDirectionReview(draft,c,published,package_){
 const intake=state.intake,needsValue=!intake.value_checkpoint?.current,needsRequirements=!intake.scaffold_current,gaps=intake.gaps||[],canShare=!needsValue&&!needsRequirements&&!gaps.length;
 const source=c?.body.source_draft,differentVersion=!!source&&(source.id!==draft.ref.id||source.revision!==draft.ref.revision),canPublish=c?.ready&&c.body.status!=='published';
 const reviewStatus=s=>({'ready-for-investigation':'Ready to investigate within limits','changes-requested':'Changes or clarification needed',published:'Published',declined:'Declined',deferred:'Deferred'})[s]||(s?s.replaceAll('-',' '):'Response needed');
 const reviewDetails=c?`<div class="direction-review-detail">${source?`<p class="caption">Reviewed Business Intent${differentVersion?' · Different from this draft':' · Same as this draft'}</p>`:''}<dl class="direction-review-responses">${(c.body.reviewers||[]).map(actor=>`<div><dt>${esc(state.actors[actor]?.role||actor)}</dt><dd>${esc(reviewStatus(c.reviews[actor]?.body.disposition))}</dd></div>`).join('')}</dl>${canPublish?button('Publish reviewed direction','intake-publish',c.ref.id,'primary'):''}</div>`:'';
 return `<section class="sponsor-panel sponsor-review-actions" aria-labelledby="direction-review-title"><h2 id="direction-review-title">Direction review</h2>
 <section class="direction-review-section" aria-labelledby="direction-review-prepare"><h3 id="direction-review-prepare">Before sharing</h3>${canShare?'<p>This version is ready to request Research and Design responses.</p>':`<div class="direction-review-prerequisites">${needsValue?`<div class="direction-review-task"><p>Review the current value proposition.</p>${button('Open value fit','sponsor-fit','','quiet small')}</div>`:''}${needsRequirements?'<div class="direction-review-task"><p>Refresh the requirements for this version.</p>'+button('Open requirements setup','sponsor-step','planning','quiet small')+'</div>':''}${gaps.length?`<div class="direction-review-task"><h4>Missing answers</h4><ul>${gaps.map(k=>`<li>${esc(intakeNames[k]||sponsorFitLabels[k]||k)}</li>`).join('')}</ul></div>`:''}</div>`}<div class="direction-review-actions"><button type="button" data-action="sponsor-share" class="primary" ${canShare?'':'disabled'}>Share Business Intent for review</button>${package_?preparedPacketButton(package_):''}</div></section>
 ${c?differentVersion&&!canPublish?`<details class="direction-review-section direction-review-history"><summary><span>Shared review</span><span class="caption">${esc(reviewStatus(c.body.status))} · Different draft</span></summary>${reviewDetails}</details>`:`<section class="direction-review-section" aria-labelledby="direction-review-shared"><h3 id="direction-review-shared">Shared review</h3><p class="caption">${esc(reviewStatus(c.body.status))}</p>${reviewDetails}</section>`:''}
 <section class="direction-review-section" aria-labelledby="direction-review-publication"><h3 id="direction-review-publication">${published?'Published direction':'Publication'}</h3>${published?button('View published Business Intent','pflow-business-intent','','quiet small'):''}<p>Publishing direction does not approve requirements.</p><details class="direction-review-publication-detail"><summary>What publication includes</summary><p>The exact Business Intent, reviewed value proposition, goal and measure versions, requirements and remaining questions. Source documents and private AI partner discussions stay private.</p></details></section>
 <footer class="direction-review-footer">${button('Home','projects-home','','quiet small')}</footer></section>`;
}
function sponsorReview(){
 const s=sponsorInfo(),f=s.brief.framing,c=currentIntakeCase(),published=state.intake.published,draft=state.intake.draft,v=draft.body.values,package_=(state.intake.preflight?.packages||[]).find(p=>p.current),sections=[...new Set(s.questions.map(q=>q.section))];
 const outline=[['core','Core Value Statement'],...sections.map((t,i)=>['section-'+i,sponsorSectionTitle(t)]),['value','Value proposition & investment'],['requirements','Requirements set up']];
 return sponsorHeading('Review Business Intent','Read it end to end, then share the saved version for direction review.','review',`<div class="sponsor-review-status"><span class="tag">${published?'Published direction exists':'Private draft'}</span>${sponsorReviewCoverage(s)}</div>`)+sponsorGuidance('review')+sponsorPublishSummary(s)+`<div class="sponsor-review-grid"><nav class="sponsor-panel sponsor-outline" aria-label="Business Intent outline">${outline.map(([id,title],i)=>`<button type="button" data-action="sponsor-scroll" data-id="${id}"><span>${String(i+1).padStart(2,'0')}</span>${esc(title)}</button>`).join('')}</nav><article class="sponsor-panel sponsor-document"><div class="sponsor-document-head"><span class="eyebrow">Business Intent</span><h2>${esc(f.name)}</h2><div class="workbench-context-row"><dl class="workbench-context-chips" aria-label="Document context"><div class="workbench-context-chip"><dt>Owner</dt><dd>${esc(state.actors[state.actor].name)}</dd></div><div class="workbench-context-chip workbench-context-chip-progress"><dt>Answered</dt><dd>${s.questions.filter(q=>sponsorAnswerHas(s.brief.answers[q.id])).length} of ${s.questions.length}</dd></div></dl><details class="record-metadata"><summary>Source details</summary><div class="metadata-content">Business Intent · ${esc(label(draft.ref))}</div></details></div></div><section id="sponsor-review-core" tabindex="-1"><div class="sponsor-doc-section-head"><h2>Core Value Statement</h2>${button('Edit','sponsor-step','framing','quiet small')}</div>${sponsorCoreRead(f,v)}<details><summary>Supporting problem notes, risks & alternatives</summary>${val('Supporting problem notes',f.summary.problem)}${val('Risks',f.summary.risk)}${val('Options',f.summary.options)}</details></section>${sections.map((section,i)=>`<section id="sponsor-review-section-${i}" tabindex="-1"><h2>${esc(sponsorSectionTitle(section))}</h2>${s.questions.filter(q=>q.section===section).map(q=>{const a=s.brief.answers[q.id];return `<div class="sponsor-doc-answer"><div class="sponsor-doc-section-head"><div class="sponsor-answer-heading"><h3>${esc(sponsorQuestionTitle(q))}</h3>${sponsorAnswerStatus(a)}</div>${button('Edit','sponsor-question',q.id,'quiet small')}</div>${!sponsorAnswerHas(a)?'<p class="caption">Not answered yet.</p>':q.kind==='roles'?a.roles.map(sponsorRoleRead).join(''):`<ul>${a.items.filter(t=>t.trim()).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}</div>`;}).join('')}</section>`).join('')}<section id="sponsor-review-value" tabindex="-1"><div class="sponsor-doc-section-head"><h2>Value proposition & investment</h2>${button('Edit','sponsor-fit','','quiet small')}</div>${Object.entries(sponsorFitLabels).filter(([k])=>v[k]).map(([k,t])=>val(t,v[k])).join('')}</section><section id="sponsor-review-requirements" tabindex="-1"><div class="sponsor-doc-section-head"><h2>Requirements set up</h2>${button('Edit','sponsor-step','planning','quiet small')}</div>${goalsRead({goals:state.goals?.goals||[],measures:state.goals?.measures||[]})}${draft.body.scaffold.map(d=>`<details><summary>${esc(d.label)}</summary>${areaRead(d,state.goals)}${(d.children||[]).map(c=>areaRead(c,state.goals)).join('')}</details>`).join('')}</section></article><aside class="sponsor-review-rail">${sponsorDirectionReview(draft,c,published,package_)}</aside></div>`;
}

let sponsorActionPending=false;
async function sponsorAction(action,id,origin){
 if(!action.startsWith('sponsor-')&&!(action==='intake-step'&&state.actor==='priya'))return false;
 if(sponsorActionPending)return true;
 sponsorActionPending=true;
 try{if(['sponsor-step','sponsor-question','sponsor-validation','sponsor-fit'].includes(action)&&typeof sponsorGoalsSaveIfDirty==='function')await sponsorGoalsSaveIfDirty();return await dispatchSponsorAction(action,id,origin);}finally{sponsorActionPending=false;}
}

// Keep the header disclosure state accurate when an edit link opens its panel.
document.addEventListener('toggle',event=>{
 const panel=event.target;
 if(!panel.matches?.('details.planning-category-settings'))return;
 const control=panel.closest('.drawer-edit')?.querySelector('[data-action="sponsor-planning-toggle"]');
 if(control)control.setAttribute('aria-expanded',String(panel.open));
},true);
